update Services
set service_name = #{serviceName}, category = #{category}, price = #{price},
    duration_minutes = #{durationMinutes}, description = #{description}, concern = #{concern}
where service_id = #{serviceId}

mapper.insert:
INSERT INTO Salon_Operating_Hours (salon_id, day_of_week, open_time, close_time)
SELECT #{salonId}, d.dow, #{openTime}, #{closeTime}
FROM (
    SELECT '월' AS dow UNION ALL SELECT '화' UNION ALL SELECT '수'
    UNION ALL SELECT '목' UNION ALL SELECT '금' UNION ALL SELECT '토'
) AS d
